<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Factories\HasFactory;
class AidRequest extends Model { use HasFactory; protected $table='requests'; protected $fillable=['beneficiary_id','category','quantity_needed','urgency','justification','item_details','alternative_categories','pickup_location','availability_window','supporting_document_path','cancellation_reason','cancelled_at','status','is_walk_in','walk_in_status','created_by_staff_id','verified_by_user_id','verification_tier','verification_state','verification_checklist','verification_notes','staff_internal_notes','referral_destination','verification_decision_reason','verification_decided_at','student_id_number']; protected $casts=['cancelled_at'=>'datetime','verification_decided_at'=>'datetime','verification_checklist'=>'array','is_walk_in'=>'boolean']; public function beneficiary(){return $this->belongsTo(User::class,'beneficiary_id');} public function verifiedBy(){return $this->belongsTo(User::class,'verified_by_user_id');} public function matches(){return $this->hasMany(DonationMatch::class,'request_id');} public function scopeFilter($q,$f){return $q->when($f['category']??null,fn($q,$v)=>$q->where('category',$v))->when($f['status']??null,fn($q,$v)=>$q->where('status',$v))->when($f['q']??null,fn($q,$v)=>$q->where('justification','like',"%$v%"));} }
